<?php $this->assign('title','Prazos e áreas da fábrica'); ?>
<h1>Prazos e áreas da fábrica</h1><section class="panel">
<?= $this->Form->create(null,['type'=>'get','class'=>'row g-3']) ?><div class="col-md-4"><?php if(isset($periodoSelecionado)): ?><?= $this->Form->hidden('entressafra_id',['value'=>$periodoSelecionado->id]) ?><?php else: ?><?= $this->Form->control('entressafra_id',['label'=>'Entressafra','options'=>$seasons,'value'=>$season,'class'=>'form-select']) ?><?php endif; ?></div><div class="col-md-4"><?= $this->Form->control('caderno_id',['label'=>'Filtrar O.S. por caderno (não define a área)','options'=>$notebooks,'empty'=>'Todos / sem caderno','value'=>$this->request->getQuery('caderno_id'),'class'=>'form-select']) ?></div><?= $this->Form->button('Consultar',['class'=>'btn btn-outline-primary']) ?><?= $this->Form->end() ?>
<p>Área da fábrica não é a equipe executante. O caderno também não define automaticamente um prazo. Classifique as O.S. após conferir sua localização. Inícios em branco continuam pendentes de conferência; nenhum início foi presumido.</p></section>
<?php foreach($rows as $r): ?><section class="panel mt-3"><h2><?= h($r['chave']==='padrao'?'Prazo padrão':($r['area_fabrica_id']?'Área: '.($areas->toArray()[$r['area_fabrica_id']]??''):'Setor executante #'.$r['setor_id'])) ?></h2>
<?= $this->Form->create(null) ?><?= $this->Form->hidden('area_fabrica_id',['value'=>$r['area_fabrica_id']]) ?><?= $this->Form->hidden('setor_id',['value'=>$r['setor_id']]) ?><div class="row g-3"><div class="col-md-4"><?= $this->Form->control('data_inicio',['label'=>'Início a conferir','type'=>'date','value'=>$r['data_inicio'],'class'=>'form-control']) ?></div><div class="col-md-4"><?= $this->Form->control('data_fim',['label'=>'Encerramento oficial','type'=>'date','value'=>$r['data_fim'],'class'=>'form-control','required'=>true]) ?></div><div class="col-md-4"><?= $this->Form->control('inicio_confirmado',['type'=>'checkbox','value'=>'1','checked'=>$r['inicio_confirmado'],'label'=>'Início conferido pelo PCM']) ?></div></div><p>Referências: <?= h(implode(', ',$service->references($r))?:'Pendentes de início conferido') ?></p><?= $this->Form->button('Salvar prazo e referências',['class'=>'btn btn-primary']) ?><?= $this->Form->end() ?></section><?php endforeach; ?>
<details class="panel mt-3"><summary>Adicionar calendário por área ou setor executante</summary><?= $this->Form->create(null) ?><?= $this->Form->control('area_fabrica_id',['label'=>'Área física','options'=>$areas,'empty'=>'Nenhuma / usar setor ou padrão','class'=>'form-select']) ?><?= $this->Form->control('setor_id',['label'=>'Setor executante (somente se o prazo valer para toda a equipe)','options'=>$sectors,'empty'=>'Nenhum','class'=>'form-select']) ?><?= $this->Form->control('data_inicio',['label'=>'Início','type'=>'date','class'=>'form-control']) ?><?= $this->Form->control('data_fim',['label'=>'Término','type'=>'date','required'=>true,'class'=>'form-control']) ?><?= $this->Form->control('inicio_confirmado',['label'=>'Início conferido','type'=>'checkbox','value'=>'1']) ?><?= $this->Form->button('Adicionar / atualizar calendário',['class'=>'btn btn-primary']) ?><?= $this->Form->end() ?></details>
<details class="panel mt-3"><summary>Cadastrar outra área física</summary><?= $this->Form->create(null) ?><?= $this->Form->hidden('acao',['value'=>'nova_area']) ?><?= $this->Form->control('nome',['label'=>'Nome da área física','required'=>true,'maxlength'=>150,'class'=>'form-control']) ?><?= $this->Form->button('Cadastrar área',['class'=>'btn btn-outline-primary']) ?><?= $this->Form->end() ?></details>
<section class="panel mt-3"><h2>Classificação física das O.S.</h2><p><?= $total ?> O.S. no filtro · Página <?= $page ?>. Selecione somente as O.S. conferidas; não são transferidas entre cadernos.</p>
<?= $this->Form->create(null,['onsubmit'=>"return confirm('Confirma a classificação física das O.S. selecionadas?');"]) ?><?= $this->Form->hidden('acao',['value'=>'classificar']) ?><div class="table-responsive"><table class="table"><thead><tr><th>Selecionar</th><th>O.S.</th><th>Equipe executante</th><th>Caderno</th><th>Área física</th><th>Prazo</th></tr></thead><tbody><?php foreach($activities as $a):$r=$service->resolve($a); ?><tr><td><input type="checkbox" name="ids[]" value="<?= h($a['id']) ?>"></td><td><?= h($a['os_numero']) ?></td><td><?= h($a['setor_nome']) ?> / <?= h($a['area_executante_totvs']) ?></td><td><?= h($a['caderno_nome']??'Sem caderno') ?></td><td><?= h($areas->toArray()[$a['area_fabrica_id']]??'Classificação pendente') ?></td><td><?= h($r['data_fim']??'Pendente de classificação') ?></td></tr><?php endforeach; ?></tbody></table></div>
<?= $this->Form->control('area_destino',['label'=>'Área física conferida','options'=>$areas,'required'=>true,'class'=>'form-select']) ?><?= $this->Form->control('caderno_destino',['label'=>'Caderno opcional (somente O.S. sem vínculo)','options'=>$notebooks,'empty'=>'Preservar caderno atual / sem caderno','class'=>'form-select']) ?><?= $this->Form->button('Confirmar classificação selecionada',['class'=>'btn btn-primary']) ?><?= $this->Form->end() ?>
<div class="d-flex gap-3 mt-3"><?php if($page>1): ?><?= $this->Html->link('Anterior',['?'=>['pagina'=>$page-1]+$this->request->getQueryParams()]) ?><?php endif; ?><?php if($page*10<$total): ?><?= $this->Html->link('Próxima',['?'=>['pagina'=>$page+1]+$this->request->getQueryParams()]) ?><?php endif; ?></div></section>
